selector_to_html = {"a[href=\"#flagquantum\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u4e3a\u4ec0\u4e48\u9700\u8981 FlagQuantum\uff1f<a class=\"headerlink\" href=\"#flagquantum\" title=\"Link to this heading\">#</a></h2><p>\u4e00\u4e2a\u91cf\u5b50\u7a0b\u5e8f\u6709\u4e09\u4e2a\u5f7c\u6b64\u72ec\u7acb\u7684\u5173\u6ce8\u70b9\uff1a\u7ebf\u8def\u3001\u6d4b\u91cf\u8bf7\u6c42\u3001\u6267\u884c\u76ee\u6807\u3002FlagQuantum \u8ba9\u5b83\u4eec\u4fdd\u6301\u663e\u5f0f\u3002</p>", "a[href=\"#id4\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u4ece\u54ea\u5f00\u59cb<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#id3\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u80fd\u529b\u6210\u719f\u5ea6<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h2><p>\u652f\u6301\u8303\u56f4\u56e0\u540e\u7aef\u4e0e\u8d1f\u8f7d\u800c\u5f02\u3002\u6bcf\u9879\u80fd\u529b\u90fd\u6709\u7b49\u7ea7\uff0c\u4e14\u7b49\u7ea7\u53ea\u9002\u7528\u4e8e\u5b9e\u9645\u9a8c\u8bc1\u8fc7\u7684\u8303\u56f4\uff1a</p>", "a[href=\"#id2\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u5165\u53e3<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#flagos\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u4e0e FlagOS \u7684\u914d\u5408\u65b9\u5f0f<a class=\"headerlink\" href=\"#flagos\" title=\"Link to this heading\">#</a></h2><p>FlagQuantum \u4f9d\u8d56 PyTorch\uff0c\u800c\u4e0d\u4f9d\u8d56\u7279\u5b9a\u5382\u5546\u8fd0\u884c\u65f6\u3002\u56fd\u4ea7\u52a0\u901f\u5668\u901a\u8fc7 FlagOS \u7edf\u4e00\u591a\u82af\u7247\u5c42\u63a5\u5165\uff0c\u7269\u7406\u8bbe\u5907\u63a2\u6d4b\u3001\u5382\u5546\u8fd0\u884c\u65f6\u4ee5\u53ca\u903b\u8f91\u8bbe\u5907 <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos:0</span></code> \u7684\u6620\u5c04\u90fd\u7531\u8be5\u5c42\u8d1f\u8d23\uff1bFlagQuantum \u81ea\u8eab\u4e0d\u542b\u4efb\u4f55\u5382\u5546\u5206\u652f\uff0c\u53ea\u8bb0\u5f55\u5b83\u6536\u5230\u7684\u8def\u7531\u8bc1\u636e\u3002\u5c42\u8fb9\u754c\u89c1<a class=\"reference internal\" href=\"architecture.html\"><span class=\"std std-doc\">\u67b6\u6784</span></a>\uff0c\u5382\u5546\u63a5\u5165\u8def\u5f84\u89c1<a class=\"reference internal\" href=\"#../user_guide/remote-execution.md\"><span class=\"xref myst\">\u8fdc\u7a0b\u6267\u884c</span></a>\u3002</p>", "a[href=\"architecture.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u67b6\u6784<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>FlagQuantum \u4e3a\u91cf\u5b50 AI \u7a0b\u5e8f\u63d0\u4f9b\u7edf\u4e00\u6a21\u578b\uff0c\u8986\u76d6\u672c\u5730\u5f00\u53d1\u3001\u52a0\u901f\u5185\u6838\u3001\u5206\u5e03\u5f0f\u6a21\u62df\u4e0e\u90e8\u7f72\uff1a</p>", "a[href=\"../getting_started/quick-start.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u5feb\u901f\u5f00\u59cb<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>\u672c\u9875\u8bad\u7ec3\u4e00\u4e2a\u53cc\u91cf\u5b50\u6bd4\u7279\u6a21\u578b\uff0c\u7136\u540e\u6f14\u793a\u5982\u4f55\u5728\u4e0d\u6539\u52a8\u6a21\u578b\u7684\u60c5\u51b5\u4e0b\u5207\u6362\u6a21\u62df\u8868\u793a\u3002</p>", "a[href=\"#id1\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u6982\u89c8<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>FlagQuantum \u662f\u4e00\u4e2a\u57fa\u4e8e PyTorch \u6784\u5efa\u7684\u5206\u5e03\u5f0f\u3001\u53ef\u5fae\u91cf\u5b50\u8ba1\u7b97\u6846\u67b6\u3002\u5b83\u628a\u91cf\u5b50\u7ebf\u8def\u53d8\u6210\u53ef\u8bad\u7ec3\u6a21\u578b\uff1a\u540c\u4e00\u4e2a\u7a0b\u5e8f\u65e2\u53ef\u4ee5\u7528 PyTorch \u5e38\u89c4\u4f18\u5316\u5668\u8bad\u7ec3\uff0c\u4e5f\u53ef\u4ee5\u7528\u4e0d\u540c\u8868\u793a\u5f62\u5f0f\u6a21\u62df\uff0c\u5728\u8d1f\u8f7d\u9700\u8981\u65f6\u8de8\u5361\u5207\u5206\uff0c\u5e76\u5728\u8fdc\u7a0b\u7b97\u529b\u6216\u91cf\u5b50\u786c\u4ef6\u4e0a\u6c42\u503c\u3002\u5b83\u5c5e\u4e8e FlagOS \u751f\u6001\u2014\u2014\u4e00\u4e2a\u7edf\u4e00\u7684\u5f00\u6e90 AI \u7cfb\u7edf\u8f6f\u4ef6\u6808\uff0c\u7528\u6765\u6574\u5408\u591a\u6837\u5316\u7684\u6a21\u578b\u3001\u7cfb\u7edf\u4e0e\u82af\u7247\u3002</p>", "a[href=\"../getting_started/install.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u5b89\u88c5 FlagQuantum<a class=\"headerlink\" href=\"#flagquantum\" title=\"Link to this heading\">#</a></h1><p>\u5f00\u59cb\u524d\u8bf7\u5148\u9605\u8bfb<a class=\"reference internal\" href=\"../getting_started/requirements.html\"><span class=\"std std-doc\">\u73af\u5883\u8981\u6c42</span></a>\u3002</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
